<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class InvestigationCaseService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly PermissionRepository $permissions,private readonly EvidenceRetentionService $evidence) {}
    private function case(string $id):array {$r=$this->row('investigation_cases','case_id',$id);$this->access->requireSite($r['site_id']);$incident=$this->row('incidents','incident_id',$r['incident_id']);if(!empty($incident['deleted_at'])||(string)$incident['site_id']!==(string)$r['site_id'])throw HttpException::notFound();return $r;}
    private function editable(array $r):void {if(!in_array($r['state'],['TRIAGE','INVESTIGATING'],true))throw HttpException::conflict('Review/closed cases are locked; return for changes or reopen first.');}
    private function user(mixed $id,mixed $site):array {$u=$this->row('users','user_id',$id);if($u['status']!=='ACTIVE'||!$this->permissions->userHasPermission((string)$u['user_id'],'investigations.manage')||($this->access->restricted((string)$u['user_id'])&&!$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:user AND site_id=:site',['company'=>$this->company(),'user'=>$u['user_id'],'site'=>$site])))throw HttpException::unprocessable('Choose an active investigation operator with access to this site.');return $u;}
    private function history(string $id,string $state,string $notes,?string $hash=null):void {$this->db->execute('INSERT INTO investigation_history(company_id,case_id,state,notes,snapshot_hash,actor_user_id,occurred_at) VALUES(:company,:id,:state,:notes,:hash,:actor,:now)',['company'=>$this->company(),'id'=>$id,'state'=>$state,'notes'=>$notes,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$this->audit->record('investigation_case',$state,$id);}
    private function contents(array $r):array {return ['incident'=>$this->row('incidents','incident_id',$r['incident_id']),'summary'=>$r['summary'],'investigator_user_id'=>$r['investigator_user_id'],'notes'=>$this->db->fetchAll('SELECT * FROM investigation_notes WHERE company_id=:company AND case_id=:id ORDER BY note_id',['company'=>$this->company(),'id'=>$r['case_id']]),'actions'=>$this->db->fetchAll('SELECT * FROM investigation_actions WHERE company_id=:company AND case_id=:id ORDER BY action_id',['company'=>$this->company(),'id'=>$r['case_id']])];}
    private function fingerprint(array $r):string {return hash('sha256',json_encode($this->contents($r),JSON_THROW_ON_ERROR));}
    public function list(array $input):array {$this->fields($input,['site_id']);$s=$this->access->requireSite($input['site_id']??null);$rows=$this->db->fetchAll('SELECT c.* FROM investigation_cases c JOIN incidents i ON i.company_id=c.company_id AND i.incident_id=c.incident_id AND i.site_id=c.site_id WHERE c.company_id=:company AND c.site_id=:site AND i.deleted_at IS NULL ORDER BY case_id DESC LIMIT 200',['company'=>$this->company(),'site'=>$s['site_id']]);foreach($rows as&$r){$r+=$this->contents($r);$r['history']=$this->db->fetchAll('SELECT state,notes,snapshot_hash,actor_user_id,occurred_at FROM investigation_history WHERE company_id=:company AND case_id=:id ORDER BY history_id',['company'=>$this->company(),'id'=>$r['case_id']]);}unset($r);return $rows;}
    public function create(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['incident_id','investigator_user_id','due_on','notes']);$i=$this->row('incidents','incident_id',$input['incident_id']??null);if(!empty($i['deleted_at']))throw HttpException::notFound();$this->access->requireSite($i['site_id']);$user=$this->user($input['investigator_user_id']??null,$i['site_id']);$due=$this->day($input['due_on']??null);if($due<gmdate('Y-m-d'))throw HttpException::unprocessable('Choose a current/future deadline.');if($this->db->fetch('SELECT case_id FROM investigation_cases WHERE company_id=:company AND incident_id=:incident',['company'=>$this->company(),'incident'=>$i['incident_id']]))throw HttpException::conflict('This incident already has an investigation; reopen it if necessary.');$notes=$this->text($input['notes']??null,2000);$this->db->execute("INSERT INTO retention_holds(company_id,category,record_id,reason,created_by_user_id,created_at) VALUES(:company,'incident',:incident,:reason,:actor,:now)",['company'=>$this->company(),'incident'=>$i['incident_id'],'reason'=>mb_substr('Investigation preservation: '.$notes,0,500),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$hold=(string)$this->db->connection()->lastInsertId();$this->db->execute('INSERT INTO investigation_cases(company_id,incident_id,site_id,investigator_user_id,created_by_user_id,due_on,hold_id,created_at) VALUES(:company,:incident,:site,:user,:actor,:due,:hold,:now)',['company'=>$this->company(),'incident'=>$i['incident_id'],'site'=>$i['site_id'],'user'=>$user['user_id'],'actor'=>$this->actor(),'due'=>$due,'hold'=>$hold,'now'=>gmdate('Y-m-d H:i:s')]);$id=(string)$this->db->connection()->lastInsertId();$this->history($id,'TRIAGE',$notes);return ['id'=>$id,'hold_id'=>$hold];});}
    public function note(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['note_type','notes','evidence_id']);$r=$this->case($id);$this->editable($r);$type=$input['note_type']??null;if(!in_array($type,['WITNESS','FINDING','ROOT_CAUSE','EVIDENCE'],true))throw HttpException::unprocessable('Choose a supported note type.');$e=null;if($type==='EVIDENCE'){$e=$this->row('incident_evidence','evidence_id',$input['evidence_id']??null);if((string)$e['incident_id']!==(string)$r['incident_id']||$e['purged_at'])throw HttpException::notFound('Evidence unavailable for this incident.');$this->evidence->download((string)$e['evidence_id']);}elseif(!empty($input['evidence_id']))throw HttpException::unprocessable('Only evidence notes can reference an original.');$this->db->execute('INSERT INTO investigation_notes(company_id,case_id,note_type,notes,evidence_id,evidence_sha256,actor_user_id,occurred_at) VALUES(:company,:id,:type,:notes,:evidence,:hash,:actor,:now)',['company'=>$this->company(),'id'=>$id,'type'=>$type,'notes'=>$this->text($input['notes']??null,10000),'evidence'=>$e['evidence_id']??null,'hash'=>$e['sha256']??null,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('investigation_note');$this->db->execute('UPDATE investigation_cases SET revision=revision+1 WHERE company_id=:company AND case_id=:id',['company'=>$this->company(),'id'=>$id]);return $result;});}
    public function upload(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['original_filename','file_base64','description','captured_at']);$r=$this->case($id);$this->editable($r);$e=$this->evidence->addEvidence($input+['incident_id'=>$r['incident_id']]);$this->note($id,['note_type'=>'EVIDENCE','notes'=>$input['description'],'evidence_id'=>$e['id']]);return $e;});}
    public function original(string $id,string $evidence):array {$r=$this->case($id);if(!$this->db->fetch('SELECT note_id FROM investigation_notes WHERE company_id=:company AND case_id=:id AND evidence_id=:evidence',['company'=>$this->company(),'id'=>$id,'evidence'=>$evidence]))throw HttpException::notFound();$e=$this->row('incident_evidence','evidence_id',$evidence);if((string)$e['incident_id']!==(string)$r['incident_id'])throw HttpException::notFound();$d=$this->evidence->download($evidence);return ['base64'=>base64_encode($d['bytes']),'filename'=>$e['original_filename'],'sha256'=>$d['sha256']];}
    public function action(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['title','owner_user_id','due_on']);$r=$this->case($id);$this->editable($r);$u=$this->user($input['owner_user_id']??null,$r['site_id']);$due=$this->day($input['due_on']??null);if($due<gmdate('Y-m-d'))throw HttpException::unprocessable('Choose a current/future action deadline.');$this->db->execute('INSERT INTO investigation_actions(company_id,case_id,title,owner_user_id,due_on) VALUES(:company,:id,:title,:owner,:due)',['company'=>$this->company(),'id'=>$id,'title'=>$this->text($input['title']??null,300),'owner'=>$u['user_id'],'due'=>$due]);$result=$this->created('investigation_action');$this->db->execute('UPDATE investigation_cases SET revision=revision+1 WHERE company_id=:company AND case_id=:id',['company'=>$this->company(),'id'=>$id]);return $result;});}
    public function complete(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','notes']);$a=$this->row('investigation_actions','action_id',$id);$r=$this->case((string)$a['case_id']);$this->editable($r);if((string)$a['owner_user_id']!==$this->actor())throw HttpException::forbidden('Only the assigned action owner can attest completion.');if($a['state']!=='OPEN'||$this->number($input['expected_revision']??null)!==(int)$a['revision'])throw HttpException::conflict('Action changed.');$this->db->execute("UPDATE investigation_actions SET state='COMPLETED',revision=revision+1,completion_notes=:notes,completed_by_user_id=:actor,completed_at=:now WHERE company_id=:company AND action_id=:id",['notes'=>$this->text($input['notes']??null,2000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->db->execute('UPDATE investigation_cases SET revision=revision+1 WHERE company_id=:company AND case_id=:id',['company'=>$this->company(),'id'=>$r['case_id']]);$this->audit->record('investigation_action','completed',$id);return ['completed'=>true];});}
    public function reassign(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','investigator_user_id','due_on','notes']);$r=$this->case($id);$this->editable($r);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Investigation changed.');$u=$this->user($input['investigator_user_id']??null,$r['site_id']);$due=$this->day($input['due_on']??null);if($due<gmdate('Y-m-d'))throw HttpException::unprocessable('Choose a current/future deadline.');$notes=$this->text($input['notes']??null,2000);$this->db->execute('UPDATE investigation_cases SET investigator_user_id=:user,due_on=:due,revision=revision+1 WHERE company_id=:company AND case_id=:id',['user'=>$u['user_id'],'due'=>$due,'company'=>$this->company(),'id'=>$id]);$this->history($id,$r['state'],'Investigator reassigned from #'.$r['investigator_user_id'].' to #'.$u['user_id'].': '.$notes);return ['reassigned'=>true];});}
    public function reassignAction(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','owner_user_id','due_on','notes']);$a=$this->row('investigation_actions','action_id',$id);$r=$this->case((string)$a['case_id']);$this->editable($r);if($a['state']!=='OPEN'||$this->number($input['expected_revision']??null)!==(int)$a['revision'])throw HttpException::conflict('Action changed or is completed.');$u=$this->user($input['owner_user_id']??null,$r['site_id']);$due=$this->day($input['due_on']??null);if($due<gmdate('Y-m-d'))throw HttpException::unprocessable('Choose a current/future deadline.');$notes=$this->text($input['notes']??null,2000);$this->db->execute('UPDATE investigation_actions SET owner_user_id=:user,due_on=:due,revision=revision+1 WHERE company_id=:company AND action_id=:id',['user'=>$u['user_id'],'due'=>$due,'company'=>$this->company(),'id'=>$id]);$this->db->execute('UPDATE investigation_cases SET revision=revision+1 WHERE company_id=:company AND case_id=:id',['company'=>$this->company(),'id'=>$r['case_id']]);$this->history((string)$r['case_id'],$r['state'],'Action #'.$id.' reassigned from #'.$a['owner_user_id'].' to #'.$u['user_id'].': '.$notes);return ['reassigned'=>true];});}
    public function transition(string $id,string $action,array $input):array {return $this->atomic(function()use($id,$action,$input){$this->fields($input,['expected_revision','notes','expected_hash']);$r=$this->case($id);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Investigation changed.');$notes=$this->text($input['notes']??null,10000);$hash=null;$summary=$r['summary'];$submitted=$r['submitted_by_user_id'];$reviewer=$r['reviewed_by_user_id'];$closed=null;
        if($action==='begin'&&$r['state']==='TRIAGE')$state='INVESTIGATING';
        elseif($action==='submit'&&$r['state']==='INVESTIGATING'){if((string)$r['investigator_user_id']!==$this->actor())throw HttpException::forbidden('The assigned investigator must submit findings.');$contents=$this->contents($r);if(!$contents['notes']||!array_filter($contents['notes'],fn($n)=>$n['note_type']==='ROOT_CAUSE')||array_filter($contents['actions'],fn($a)=>$a['state']!=='COMPLETED'))throw HttpException::conflict('Record findings/root cause and complete all corrective actions before review.');$state='REVIEW';$summary=$notes;$r['summary']=$summary;$hash=$this->fingerprint($r);$submitted=$this->actor();}
        elseif(in_array($action,['approve','return'],true)&&$r['state']==='REVIEW'){if($this->actor()===(string)$r['investigator_user_id']||$this->actor()===(string)$r['submitted_by_user_id'])throw HttpException::forbidden('A different reviewer must assess this case.');if($action==='approve'){if(!is_string($input['expected_hash']??null)||!hash_equals($r['review_hash'],$input['expected_hash'])||!hash_equals($r['review_hash'],$this->fingerprint($r)))throw HttpException::conflict('Review contents changed; return for fresh submission.');foreach($this->contents($r)['notes']as$n)if($n['evidence_id']){ $e=$this->row('incident_evidence','evidence_id',$n['evidence_id']);if(!hash_equals($n['evidence_sha256'],$e['sha256']))throw HttpException::conflict('Linked evidence changed.');$this->evidence->download((string)$n['evidence_id']);}$state='CLOSED';$closed=gmdate('Y-m-d H:i:s');$hash=$r['review_hash'];}else $state='INVESTIGATING';$reviewer=$this->actor();}
        elseif($action==='reopen'&&$r['state']==='CLOSED')$state='INVESTIGATING';else throw HttpException::conflict('This investigation transition is unavailable.');
        $this->db->execute('UPDATE investigation_cases SET state=:state,revision=revision+1,summary=:summary,review_hash=:hash,submitted_by_user_id=:submitted,reviewed_by_user_id=:reviewer,closed_at=:closed WHERE company_id=:company AND case_id=:id',['state'=>$state,'summary'=>$summary,'hash'=>$hash,'submitted'=>$submitted,'reviewer'=>$reviewer,'closed'=>$closed,'company'=>$this->company(),'id'=>$id]);$this->history($id,$state,$notes,$hash);return ['state'=>$state,'note'=>'The evidence preservation hold remains until separately reviewed and released by an authorised retention administrator. Incident status is managed separately.'];
    });}
}
